P=Path(__file__).resolve().parent
sys.path.insert(0,str(P.parents[1]))
from readability import bullet_prose
TABLE_MAP={'Student':'student','Course':'course','Registration':'registration','Degree Examination Result':'degree_examination_result','Task':'task','Simulation Module':'simulation_module','Thesis':'thesis','Student Simulation Experiment Result':'student_simulation_experiment_result','Assignment':'assignment','Instructor':'instructor','Assignment Grading':'assignment_grading'}
ROLE={'student':'Unified student information from the three university examples','course':'Course offerings and planned teaching schedules','registration':'Successful registrations; one retained row per student and course','degree_examination_result':'Examination results including retakes','task':'Course-design task descriptions and scheduled task periods','simulation_module':'Simulation module descriptions and example code','thesis':'Student theses with actual submission times','student_simulation_experiment_result':'Student simulation results with actual experiment-completion times','assignment':'Student assignment content; submission time is not recorded','instructor':'Instructor information from the assignment-management example','assignment_grading':'Every recorded grading action, including regrading'}
DESC={'student_id':'Student identifier shared across the three combined examples','name':'Student name','date_of_birth':'Birth date; not an academic event','phone_number':'Student contact number','home_address':'Student postal address','registration_eligibility':'Current eligibility, ELIGIBLE or INELIGIBLE; changes are not timestamped','class':'Student class or cohort','major':'Student major','course_id':'Course-offering identifier','course_name':'Course title','credits':'Academic credit units','instructor':'Instructor name as stored in the registration source; no FK to instructor is assumed','class_time':'Planned teaching time; not proof that a class occurred','class_location':'Planned teaching location','registration_time':'Actual successful registration time in UTC','status':'Current registration status; REGISTERED in the simulated rows; no change history','result_id':'Unique examination-result identifier','examination_name':'Degree examination name','grade':'Examination score, 0 to 100; 60 is the simulated passing threshold','examination_date':'Actual examination time in UTC; not score-publication time','task_id':'Course-design task identifier','task_title':'Task title','task_description':'Task description','task_start_date':'Scheduled task-period start; not an observed student action','task_end_date':'Scheduled task deadline; not proof of completion','task_location':'Task location','module_id':'Simulation module identifier','module_name':'Module name','module_type':'Simulation method, such as PCM or DPCM','module_description':'Module description','module_code':'Example module code; not an event code','thesis_id':'Thesis identifier','thesis_title':'Thesis title','thesis_content':'Submitted thesis content','submission_date':'Actual thesis-submission time in UTC','simulation_date':'Actual experiment-completion time in UTC; this interpretation is an added simulation assumption','simulation_result_data':'Stored experiment output; not a timestamp','result_analysis':'Student analysis of the experiment result','assignment_id':'Assignment identifier','assignment_content':'Submitted assignment content; actual submission time is absent','instructor_id':'Instructor identifier','instructor_name':'Instructor name','course':'Instructor course label from the assignment source; no declared FK to course','grading_time':'Actual grading time in UTC; regrading creates another composite-key row','score':'Assignment grade, 0 to 100','evaluation':'Instructor feedback'}
RULES=['The original default questions use students as cases. Object-view questions use the alternative case tables and scope rules listed in the task catalog.','An examination-result row records one Degree Examination Taken event at examination_date, not score publication.','A registration row records one Course Registered event at registration_time.','The default student timeline includes all recorded examinations, registrations, assignment grading, simulation-experiment completions and thesis submissions linked to that student.','A grading event belongs to the student through assignment_grading.assignment_id → assignment.assignment_id → assignment.student_id. Do not join its instructor course label to every student registration.','Simulation-result and grading composite keys retain repeated actions at different times. Each occurrence appears once.','A passing examination score of at least 60 enables subsequent registration in the simulation; the source does not define this threshold.','Student ID and Name denote shared student information across the three sources. Class is merged between two sources; Major is retained from the course-design source. This shared identity is an integration assumption.','The student-course registration key is preserved; withdrawals and repeat registrations are not invented.','Task start/end dates and course schedules are plans, not observed student actions. The source has no task-to-student or task-to-experiment link; none is invented.','Instructor course labels and course.instructor are text fields retained from different sources. No unprovided FK is inferred between them.','Actual event times use UTC. simulation_date is interpreted as experiment completion, and submission_date as thesis submission. These meanings are documented adaptations.','Assignment content does not timestamp assignment submission. Notifications, withdrawals, result publication and eligibility changes cannot be reconstructed.','Students with no selected events remain in the separately declared case population. The full timeline groups academic actions without asserting they belong to one course or one causal chain.']
def write(n,s):
 p=P/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(bullet_prose(s) if p.suffix=='.md' else s,encoding='utf-8')
def js(n,o):write(n,json.dumps(o,indent=2)+'\n')
def jl(n,rows):write(n,''.join(json.dumps(r)+'\n' for r in rows))
def column(table,a):return 'instructor_name' if table=='Instructor' and a=='Name' else a.lower().replace(' ','_')
