 md+='\n## Business rules\n\n'+'\n'.join('- '+r for r in RULES)+'\n';write('input/data_dictionary.md',md)
 totals=dict(source_table_definitions=sum(len(o['answer']) for o in originals),combined_tables=len(tables),source_attribute_definitions=sum(len(t['Attributes']) for o in originals for t in o['answer'].values()),combined_columns=sum(len(t['columns']) for t in tables),retained_fk_relationships=sum(len(t['foreign_keys']) for t in tables))
 js('design/adaptation_report.json',dict(source_records=[dict(id=o['id'],tables=len(o['answer']),attributes=sum(len(t['Attributes']) for t in o['answer'].values()),all_tables_columns_pk_fk_retained=True) for o in originals],**totals,merged_tables=['Three Student definitions merged by shared Student ID; overlapping Name and Class attributes unified'],new_tables=0,new_columns=0,new_foreign_keys=0,additions=['Shared student identity across three otherwise separate source examples','SQL types, constraints, UTC event-time meanings','Synthetic score threshold, scenario order and questions'],source_gaps=['No assignment-submission or notification times','No withdrawal/status-change history','No links between tasks and experiments or students','No FK from instructor course labels to course offerings']))
 js('design/conceptual_model.json',dict(entities=list(merged),relations=[f['parent_table']+' 1:N '+t['table'] for t in tables for f in t['foreign_keys']],status='Integrated locally from three original logical schemas; shared student identity is an authored assumption'))
 write('design/requirements.md','# UniversityFlow combined execution requirements\n\n- Combine the three preserved RSchema course-registration, course-design and assignment-management examples.\n- Merge only student identities and overlapping student fields; retain every source table role, attribute and declared key relationship.\n- Use 11 tables to record examinations, registrations, assignment grading, simulation experiments and thesis submissions.\n- Preserve original composite keys for registrations, repeated grading and repeated experiments.\n- Attribute grading events to students through assignment records.\n- Task schedules and course schedules are not actual student events.\n- Document missing submission, notification and withdrawal times as unsupported.\n')
 db=P/'input/database.sqlite';db.unlink(missing_ok=True);con=sqlite3.connect(db);con.row_factory=sqlite3.Row;con.executescript(ddl)
