  gold.append(dict(question_id=qid,category=kind,answerability='answerable',process_view=dict(case_concept='Student',activities=acts,scope_rule=RULES[3]),es=es));p=P/('private/gold_logs/'+qid+'.csv');p.parent.mkdir(parents=True,exist_ok=True)
  with p.open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=['event_id','case_id','activity','timestamp']);w.writeheader();w.writerows(expected)
